using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using ShikshaMitra.Students;
using ShikshaMitra.Students.StudentEnrollments.Admissions;
using ShikshaMitra.Students.StudentEnrollments.Onboarding;
using Volo.Abp.EntityFrameworkCore.Modeling;

namespace ShikshaMitra.EntityFrameworkCore.Students.StudentEnrollments.Admissions;

public class AdmissionApplicationConfiguration : IEntityTypeConfiguration<AdmissionApplication>, IEntityTypeConfiguration<AdmissionApplicationWorkflowInstance>, IEntityTypeConfiguration<AdmissionApplicationStageInstance>, IEntityTypeConfiguration<AdmissionWorkflowTransitionHistory>, IEntityTypeConfiguration<AdmissionFormInstance>, IEntityTypeConfiguration<AdmissionFormFieldValue>, IEntityTypeConfiguration<AdmissionFormSubmission>, IEntityTypeConfiguration<AdmissionFormChangeHistory>, IEntityTypeConfiguration<AdmissionActivity>, IEntityTypeConfiguration<AdmissionApplicationDecisionHistory>
{
	public void Configure(EntityTypeBuilder<AdmissionApplication> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionApplications", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.Property(x => x.ApplicationNumber).IsRequired().HasMaxLength(64); b.HasIndex(x => new { x.TenantId, x.ApplicationNumber }).IsUnique(); b.HasIndex(x => new { x.TenantId, x.ApplicantId, x.AdmissionOfferingId }).IsUnique(); b.HasIndex(x => new { x.TenantId, x.AdmissionOfferingId, x.Status }).HasDatabaseName("IX_AdmissionApplications_OfferingStatus"); b.HasIndex(x => new { x.TenantId, x.OnboardingCaseId }).IsUnique().HasFilter("\"OnboardingCaseId\" IS NOT NULL AND \"IsDeleted\" = false"); b.HasOne<AdmissionOffering>().WithMany().HasForeignKey(x => x.AdmissionOfferingId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Student>().WithMany().HasForeignKey(x => x.StudentId).OnDelete(DeleteBehavior.Restrict); b.HasOne<StudentOnboardingCase>().WithMany().HasForeignKey(x => x.OnboardingCaseId).OnDelete(DeleteBehavior.Restrict); }
	void IEntityTypeConfiguration<AdmissionApplicationWorkflowInstance>.Configure(EntityTypeBuilder<AdmissionApplicationWorkflowInstance> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionApplicationWorkflowInstances", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.HasIndex(x => new { x.TenantId, x.ApplicationId }).IsUnique(); b.HasIndex(x => new { x.TenantId, x.Status }); b.HasOne<AdmissionApplication>().WithMany().HasForeignKey(x => x.ApplicationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<AdmissionWorkflowDefinition>().WithMany().HasForeignKey(x => x.WorkflowDefinitionId).OnDelete(DeleteBehavior.Restrict); }
	void IEntityTypeConfiguration<AdmissionApplicationStageInstance>.Configure(EntityTypeBuilder<AdmissionApplicationStageInstance> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionApplicationStageInstances", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.Property(x => x.Code).IsRequired().HasMaxLength(64); b.Property(x => x.Name).IsRequired().HasMaxLength(128); b.Property(x => x.CompletionReason).HasMaxLength(512); b.HasIndex(x => new { x.TenantId, x.WorkflowInstanceId, x.DisplayOrder }); b.HasOne<AdmissionApplicationWorkflowInstance>().WithMany().HasForeignKey(x => x.WorkflowInstanceId).OnDelete(DeleteBehavior.Cascade); b.HasOne<AdmissionWorkflowStageDefinition>().WithMany().HasForeignKey(x => x.DefinitionStageId).OnDelete(DeleteBehavior.Restrict); }
	void IEntityTypeConfiguration<AdmissionWorkflowTransitionHistory>.Configure(EntityTypeBuilder<AdmissionWorkflowTransitionHistory> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionWorkflowTransitionHistory", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.Property(x => x.IdempotencyKey).IsRequired().HasMaxLength(128); b.Property(x => x.Reason).HasMaxLength(512); b.Property(x => x.ConditionEvaluationSnapshotJson).HasColumnType("text"); b.HasIndex(x => new { x.TenantId, x.WorkflowInstanceId, x.IdempotencyKey }).IsUnique().HasFilter("\"IsDeleted\" = false"); b.HasIndex(x => new { x.TenantId, x.ApplicationId, x.OccurredAt }); b.HasOne<AdmissionApplication>().WithMany().HasForeignKey(x => x.ApplicationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<AdmissionApplicationWorkflowInstance>().WithMany().HasForeignKey(x => x.WorkflowInstanceId).OnDelete(DeleteBehavior.Cascade); }
	void IEntityTypeConfiguration<AdmissionFormInstance>.Configure(EntityTypeBuilder<AdmissionFormInstance> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionFormInstances", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.HasIndex(x => new { x.TenantId, x.ApplicationId }).IsUnique(); b.HasIndex(x => new { x.TenantId, x.Status }); b.HasOne<AdmissionApplication>().WithMany().HasForeignKey(x => x.ApplicationId).OnDelete(DeleteBehavior.Restrict); b.HasOne<AdmissionFormDefinition>().WithMany().HasForeignKey(x => x.FormDefinitionId).OnDelete(DeleteBehavior.Restrict); }
	void IEntityTypeConfiguration<AdmissionFormFieldValue>.Configure(EntityTypeBuilder<AdmissionFormFieldValue> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionFormFieldValues", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.Property(x => x.FieldCode).IsRequired().HasMaxLength(128); b.Property(x => x.ValueJson).HasColumnType("text"); b.HasIndex(x => new { x.FormInstanceId, x.FieldCode }).IsUnique(); b.HasOne<AdmissionFormInstance>().WithMany().HasForeignKey(x => x.FormInstanceId).OnDelete(DeleteBehavior.Cascade); }
	void IEntityTypeConfiguration<AdmissionFormSubmission>.Configure(EntityTypeBuilder<AdmissionFormSubmission> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionFormSubmissions", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.Property(x => x.SnapshotJson).HasColumnType("text").IsRequired(); b.HasIndex(x => new { x.TenantId, x.FormInstanceId, x.AttemptNumber }).IsUnique(); b.HasIndex(x => new { x.TenantId, x.ApplicationId, x.SubmittedAt }); b.HasOne<AdmissionFormInstance>().WithMany().HasForeignKey(x => x.FormInstanceId).OnDelete(DeleteBehavior.Restrict); b.HasOne<AdmissionApplication>().WithMany().HasForeignKey(x => x.ApplicationId).OnDelete(DeleteBehavior.Restrict); }
	void IEntityTypeConfiguration<AdmissionFormChangeHistory>.Configure(EntityTypeBuilder<AdmissionFormChangeHistory> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionFormChangeHistories", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.Property(x => x.ChangeType).IsRequired().HasMaxLength(64); b.Property(x => x.ChangedFieldsJson).HasColumnType("text"); b.HasIndex(x => new { x.TenantId, x.FormInstanceId, x.OccurredAt }); b.HasOne<AdmissionFormInstance>().WithMany().HasForeignKey(x => x.FormInstanceId).OnDelete(DeleteBehavior.Cascade); b.HasOne<AdmissionApplication>().WithMany().HasForeignKey(x => x.ApplicationId).OnDelete(DeleteBehavior.Restrict); }
	void IEntityTypeConfiguration<AdmissionActivity>.Configure(EntityTypeBuilder<AdmissionActivity> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionActivities", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.Property(x => x.ActivityType).IsRequired().HasMaxLength(64); b.Property(x => x.Description).IsRequired().HasMaxLength(512); b.Property(x => x.MetadataJson).HasColumnType("text"); b.HasIndex(x => new { x.TenantId, x.ApplicantId, x.OccurredAt }); b.HasIndex(x => new { x.TenantId, x.ApplicationId, x.OccurredAt }); }
	void IEntityTypeConfiguration<AdmissionApplicationDecisionHistory>.Configure(EntityTypeBuilder<AdmissionApplicationDecisionHistory> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionApplicationDecisionHistories", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.Property(x => x.Reason).HasMaxLength(512); b.Property(x => x.Action).HasMaxLength(32); b.Property(x => x.IdempotencyKey).HasMaxLength(80); b.Property(x => x.MetadataJson).HasColumnType("text"); b.HasIndex(x => new { x.TenantId, x.ApplicationId, x.OccurredAt }); b.HasIndex(x => new { x.TenantId, x.ApplicationId, x.StageInstanceId, x.IdempotencyKey }).IsUnique().HasDatabaseName("UX_AdmissionDecisionHistory_Stage_Idempotency").HasFilter("\"IsDeleted\" = false"); b.HasOne<AdmissionApplication>().WithMany().HasForeignKey(x => x.ApplicationId).OnDelete(DeleteBehavior.Cascade); }
}
